CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY, number TEXT NOT NULL, level TEXT NOT NULL CHECK(level IN ('ПТО','ССО')), year INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, login TEXT NOT NULL, password TEXT NOT NULL, roles TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, stamp TEXT NOT NULL DEFAULT '', groupId INTEGER REFERENCES groups(id), book TEXT UNIQUE, subgroup INTEGER CHECK(subgroup IN (1,2)));
CREATE INDEX IF NOT EXISTS users_login ON users(login);
CREATE TABLE IF NOT EXISTS curators(userId INTEGER REFERENCES users(id), groupId INTEGER REFERENCES groups(id), PRIMARY KEY(userId,groupId));
CREATE TABLE IF NOT EXISTS packages(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, starts TEXT NOT NULL, ends TEXT NOT NULL, anchor TEXT NOT NULL, week INTEGER NOT NULL, digest TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, updated TEXT, UNIQUE(kind,starts,ends,digest));
CREATE UNIQUE INDEX IF NOT EXISTS current_base ON packages(kind) WHERE kind='base' AND published=1;
CREATE UNIQUE INDEX IF NOT EXISTS current_changes ON packages(starts) WHERE kind='changes' AND published=1;
CREATE TABLE IF NOT EXISTS lessons(id INTEGER PRIMARY KEY, packageId INTEGER NOT NULL REFERENCES packages(id) ON DELETE CASCADE, groupId INTEGER REFERENCES groups(id), groupNumber TEXT NOT NULL, level TEXT NOT NULL, day INTEGER NOT NULL, slot INTEGER NOT NULL, subgroup INTEGER NOT NULL, week INTEGER NOT NULL, subject TEXT NOT NULL, teacher TEXT NOT NULL, room TEXT NOT NULL, status TEXT NOT NULL, source TEXT NOT NULL, issue TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS lesson_package ON lessons(packageId,groupId,day);
CREATE TABLE IF NOT EXISTS subjects(id INTEGER PRIMARY KEY, owner INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subject_groups(subjectId INTEGER REFERENCES subjects(id), groupId INTEGER REFERENCES groups(id), PRIMARY KEY(subjectId,groupId));
CREATE TABLE IF NOT EXISTS materials(id INTEGER PRIMARY KEY, subjectId INTEGER NOT NULL REFERENCES subjects(id), title TEXT NOT NULL, url TEXT, filename TEXT, content BLOB);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY, author INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL, topic TEXT NOT NULL, audience TEXT NOT NULL, published TEXT, url TEXT, filename TEXT, content BLOB);
CREATE TABLE IF NOT EXISTS post_groups(postId INTEGER REFERENCES posts(id), groupId INTEGER REFERENCES groups(id), PRIMARY KEY(postId,groupId));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, author INTEGER NOT NULL REFERENCES users(id), recipient INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL, deadline TEXT, status TEXT);
CREATE TABLE IF NOT EXISTS message_history(id INTEGER PRIMARY KEY, messageId INTEGER NOT NULL REFERENCES messages(id), status TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, author INTEGER NOT NULL REFERENCES users(id), operation TEXT NOT NULL, target INTEGER NOT NULL, created TEXT NOT NULL);